import {
  VisArea,
  VisAreaSelectors,
  VisAxis,
  VisDonut,
  VisDonutSelectors,
  VisGroupedBar,
  VisGroupedBarSelectors,
  VisLine,
  VisLineSelectors,
  VisSingleContainer,
  VisStackedBar,
  VisStackedBarSelectors,
  VisTooltip,
  VisXYContainer,
} from "@unovis/react";
import { CurveType } from "@unovis/ts";
import { type HTMLAttributes, type ReactNode, useMemo } from "react";
import { ChartContainer } from "./ChartContainer";
import { ChartCrosshair } from "./ChartCrosshair";
import { ChartLegendContent } from "./ChartLegendContent";
import type { ChartConfig, ChartPaletteRole, ChartTableSeries } from "./chart";
import type { Rounded } from "./form";
import type { IconComponent } from "./Icon";
import type { ThemeInput } from "./theme";
import type { SemanticColor } from "./types";

export type ChartsType = "line" | "area" | "bar" | "donut" | "doughnut";
export type ChartsBarMode = "grouped" | "stacked";
export type ChartsAreaFill = "gradient" | "solid" | "none";

export interface ChartSeries {
  key?: string;
  label: string;
  data: readonly number[];
  color?: SemanticColor | "neutral";
  icon?: IconComponent;
}

interface XYDatum {
  index: number;
  label: string;
  values: number[];
}

interface DonutDatum {
  key: string;
  label: string;
  value: number;
  color: string;
}

export interface ChartsProps extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  title: string;
  description?: string;
  type?: ChartsType;
  labels: readonly string[];
  series: readonly ChartSeries[];
  colors?: readonly SemanticColor[];
  config?: ChartConfig;
  barMode?: ChartsBarMode;
  loading?: boolean;
  error?: string;
  emptyText?: string;
  showGrid?: boolean;
  showXAxis?: boolean;
  showYAxis?: boolean;
  showTooltip?: boolean;
  showLegend?: boolean;
  showCaption?: boolean;
  showTable?: boolean;
  responsive?: boolean;
  areaFill?: ChartsAreaFill;
  width?: number;
  height?: number;
  rounded?: Rounded;
  labelFormatter?: (label: string, index: number) => string;
  valueFormatter?: (value: number, series: ChartSeries, index: number) => string;
  theme?: ThemeInput;
  center?: ReactNode;
}

const defaultRoles: readonly ChartPaletteRole[] = ["primary", "secondary", "accent", "neutral"];
const areaFillOpacity: Readonly<Record<ChartsAreaFill, readonly [number, number]>> = {
  gradient: [0.5, 0.02],
  solid: [0.24, 0.24],
  none: [0, 0],
};
const plotStyle = ".balsa-chart-plot{display:block;position:relative;width:100%}";

const x = (datum: XYDatum) => datum.index;

function escapeHtml(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}

function dashArray(_: XYDatum[], index: number): number[] {
  return index % 3 === 1 ? [7, 4] : index % 3 === 2 ? [2, 4] : [];
}

export function Charts({
  title,
  description,
  type = "bar",
  labels,
  series,
  colors,
  config: explicitConfig,
  barMode = "grouped",
  loading = false,
  error,
  emptyText = "No chart data.",
  showGrid = true,
  showXAxis = true,
  showYAxis = true,
  showTooltip = true,
  showLegend = true,
  showCaption = true,
  showTable = false,
  responsive = true,
  areaFill = "gradient",
  width,
  height = 260,
  rounded,
  labelFormatter = (label: string) => label,
  valueFormatter = (value: number) => new Intl.NumberFormat().format(value),
  theme,
  center,
  ...domProps
}: ChartsProps) {
  const normalizedType = type === "doughnut" ? "donut" : type;
  const seriesKeys = series.map((item, index) => item.key ?? `series-${index}`);
  const empty = !series.length || !labels.length || series.every((item) => !item.data.length);
  const xyData = labels.map((label, index) => ({
    index,
    label,
    values: series.map((item) => item.data[index] ?? 0),
  }));
  const y = series.map((_, seriesIndex) => (datum: XYDatum) => datum.values[seriesIndex] ?? 0);
  const cornerRadius = ({ none: 0, sm: 2, md: 4, lg: 6, xl: 8, "2xl": 12, "3xl": 16, full: 9999 } satisfies Record<Rounded, number>)[rounded ?? "lg"];
  const config = useMemo<ChartConfig>(() => {
    if (explicitConfig) return explicitConfig;
    if (normalizedType === "donut") {
      return Object.fromEntries(labels.map((label, index) => [
        `segment-${index}`,
        {
          label: labelFormatter(label, index),
          color: series[0]?.color ?? colors?.[index % (colors.length || 1)] ?? defaultRoles[index % defaultRoles.length]!,
          icon: series[0]?.icon,
        },
      ]));
    }
    return Object.fromEntries(series.map((item, index) => [
      seriesKeys[index]!,
      {
        label: item.label,
        color: item.color ?? colors?.[index % (colors.length || 1)] ?? defaultRoles[index % defaultRoles.length]!,
        icon: item.icon,
      },
    ]));
  }, [colors, explicitConfig, labelFormatter, labels, normalizedType, series, seriesKeys]);
  const tableSeries: ChartTableSeries[] = series.map((item, index) => ({
    key: seriesKeys[index]!,
    label: item.label,
    data: item.data,
  }));

  function labelTick(tick: number | Date): string {
    const index = typeof tick === "number" ? Math.round(tick) : 0;
    return labelFormatter(labels[index] ?? "", index);
  }

  function valueTick(tick: number | Date): string {
    return valueFormatter(Number(tick), series[0] ?? { label: "Value", data: [] }, 0);
  }

  function tableValueFormatter(value: number, tableItem: ChartTableSeries, index: number): string {
    return valueFormatter(
      value,
      series.find((item, seriesIndex) => (item.key ?? `series-${seriesIndex}`) === tableItem.key)
        ?? { label: tableItem.label, data: tableItem.data },
      index,
    );
  }

  function tooltipTemplate(resolvedColors: Readonly<Record<string, string>>, datum: XYDatum): string {
    const rows = series.map((item, index) => `<div class="balsa-chart-tooltip-row"><span class="balsa-chart-tooltip-marker" style="background:${escapeHtml(resolvedColors[seriesKeys[index]!] ?? "currentColor")}"></span><span>${escapeHtml(item.label)}</span><strong>${escapeHtml(valueFormatter(datum.values[index] ?? 0, item, datum.index))}</strong></div>`).join("");
    return `<div class="balsa-chart-tooltip-content"><div class="balsa-chart-tooltip-label">${escapeHtml(labelFormatter(datum.label, datum.index))}</div>${rows}</div>`;
  }

  function colorsArray(resolvedColors: Readonly<Record<string, string>>): string[] {
    return seriesKeys.map((key) => resolvedColors[key] ?? "currentColor");
  }

  function areaDefs(resolvedColors: Readonly<Record<string, string>>): string {
    const [top, bottom] = areaFillOpacity[areaFill];
    return seriesKeys.map((key, index) => {
      const color = escapeHtml(resolvedColors[key] ?? "currentColor");
      return `<linearGradient id="balsa-area-${index}" x1="0" x2="0" y1="0" y2="1">`
        + `<stop offset="0%" stop-color="${color}" stop-opacity="${top}"/>`
        + `<stop offset="100%" stop-color="${color}" stop-opacity="${bottom}"/>`
        + `</linearGradient>`;
    }).join("");
  }

  function donutData(resolvedColors: Readonly<Record<string, string>>): DonutDatum[] {
    const source = series[0];
    return labels.map((label, index) => ({
      key: `segment-${index}`,
      label,
      value: source?.data[index] ?? 0,
      color: resolvedColors[`segment-${index}`] ?? "currentColor",
    }));
  }

  function donutTooltip(datum: DonutDatum): string {
    const source = series[0] ?? { label: "Value", data: [] };
    return `<div class="balsa-chart-tooltip-content"><div class="balsa-chart-tooltip-row"><span class="balsa-chart-tooltip-marker" style="background:${escapeHtml(datum.color)}"></span><span>${escapeHtml(datum.label)}</span><strong>${escapeHtml(valueFormatter(datum.value, source, labels.indexOf(datum.label)))}</strong></div></div>`;
  }

  return (
    <>
      <style>{plotStyle}</style>
      <ChartContainer
        {...domProps}
        data-balsa="charts"
        data-type={normalizedType}
        data-bar-mode={barMode}
        title={title}
        description={description}
        config={config}
        labels={labels}
        tableSeries={tableSeries}
        loading={loading}
        error={error}
        empty={empty}
        emptyText={emptyText}
        showCaption={showCaption}
        showTable={showTable}
        labelFormatter={labelFormatter}
        valueFormatter={tableValueFormatter}
        responsive={responsive}
        width={width}
        height={height}
        rounded={rounded}
        theme={theme}
      >
        {(slotProps) => (
          <>
            {normalizedType === "donut" ? (
              <VisSingleContainer
                data={donutData(slotProps.colors)}
                width={slotProps.width}
                height={slotProps.height}
                duration={slotProps.reducedMotion ? 0 : undefined}
                className="balsa-chart-plot"
              >
                <VisDonut
                  value={(datum: DonutDatum) => datum.value}
                  color={(datum: DonutDatum) => datum.color}
                  padAngle={0.025}
                  cornerRadius={Math.min(cornerRadius, 8)}
                  arcWidth={28}
                />
                {showTooltip ? (
                  <VisTooltip
                    triggers={{ [VisDonutSelectors.segment]: donutTooltip }}
                    className="balsa-chart-tooltip"
                  />
                ) : null}
              </VisSingleContainer>
            ) : (
              <VisXYContainer
                data={xyData}
                width={slotProps.width}
                height={slotProps.height}
                duration={slotProps.reducedMotion ? 0 : undefined}
                svgDefs={normalizedType === "area" ? areaDefs(slotProps.colors) : undefined}
                yDomain={[0, undefined]}
                className="balsa-chart-plot"
              >
                {normalizedType === "line" ? (
                  <VisLine
                    x={x}
                    y={y}
                    color={colorsArray(slotProps.colors)}
                    lineWidth={2}
                    curveType={CurveType.MonotoneX}
                    lineDashArray={dashArray}
                    highlightOnHover
                  />
                ) : null}
                {normalizedType === "area" ? (
                  <VisArea
                    x={x}
                    y={y}
                    color={seriesKeys.map((_, index) => `url(#balsa-area-${index})`)}
                    lineColor={colorsArray(slotProps.colors)}
                    lineDashArray={dashArray}
                    lineWidth={2}
                    curveType={CurveType.MonotoneX}
                    line
                  />
                ) : null}
                {normalizedType === "bar" && barMode === "grouped" ? (
                  <VisGroupedBar
                    x={x}
                    y={y}
                    color={colorsArray(slotProps.colors)}
                    groupPadding={0.18}
                    barPadding={0.08}
                    roundedCorners={cornerRadius}
                  />
                ) : null}
                {normalizedType === "bar" && barMode === "stacked" ? (
                  <VisStackedBar
                    x={x}
                    y={y}
                    color={colorsArray(slotProps.colors)}
                    barPadding={0.22}
                    roundedCorners={cornerRadius}
                  />
                ) : null}
                {showXAxis ? (
                  <VisAxis type="x" gridLine={false} domainLine={false} tickLine={false} tickFormat={labelTick} numTicks={labels.length} />
                ) : null}
                {showYAxis ? (
                  <VisAxis type="y" gridLine={showGrid} domainLine={false} tickLine={false} tickFormat={valueTick} />
                ) : null}
                {showTooltip ? (
                  <ChartCrosshair x={x} y={y} template={(datum: XYDatum) => tooltipTemplate(slotProps.colors, datum)} />
                ) : null}
                {showTooltip ? (
                  <VisTooltip
                    triggers={{
                      [VisLineSelectors.line]: (datum: XYDatum) => tooltipTemplate(slotProps.colors, datum),
                      [VisAreaSelectors.area]: (datum: XYDatum) => tooltipTemplate(slotProps.colors, datum),
                      [VisGroupedBarSelectors.bar]: (datum: XYDatum) => tooltipTemplate(slotProps.colors, datum),
                      [VisStackedBarSelectors.bar]: (datum: XYDatum) => tooltipTemplate(slotProps.colors, datum),
                    }}
                    className="balsa-chart-tooltip"
                  />
                ) : null}
              </VisXYContainer>
            )}
            {normalizedType === "donut" && center ? (
              <div className="pointer-events-none absolute inset-0 grid place-items-center">
                {center}
              </div>
            ) : null}
            {showLegend ? <ChartLegendContent className="mt-balsa-md" /> : null}
          </>
        )}
      </ChartContainer>
    </>
  );
}

import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { mergeClasses } from "./classes";
import type { Rounded } from "./form";
import { Spinner } from "./Spinner";
import type { ThemeInput } from "./theme";
import {
  BalsaThemeContext,
  useResolvedThemeProps,
} from "./theme-context";
import {
  BalsaChartContext,
  ensureChartContrast,
  type ChartConfig,
  type ChartPaletteRole,
  type ChartTableSeries,
} from "./chart";

export interface ChartPlotSlot {
  width: number;
  height: number;
  colors: Readonly<Record<string, string>>;
  reducedMotion: boolean;
}

export interface ChartContainerProps extends Omit<HTMLAttributes<HTMLElement>, "children" | "title"> {
  "data-balsa"?: string;
  title: string;
  description?: string;
  config: ChartConfig;
  labels?: readonly string[];
  tableSeries?: readonly ChartTableSeries[];
  loading?: boolean;
  error?: string;
  empty?: boolean;
  emptyText?: string;
  showTable?: boolean;
  showCaption?: boolean;
  responsive?: boolean;
  width?: number;
  height?: number;
  rounded?: Rounded;
  labelFormatter?: (label: string, index: number) => string;
  valueFormatter?: (value: number, series: ChartTableSeries, index: number) => string;
  theme?: ThemeInput;
  children?: (slot: ChartPlotSlot) => ReactNode;
}

const defaultRoles: readonly ChartPaletteRole[] = ["primary", "secondary", "accent", "neutral"];

function token(role: ChartPaletteRole): string {
  if (role === "neutral") return "foreground";
  return role;
}

export function ChartContainer(rawProps: ChartContainerProps) {
  const { props, theme } = useResolvedThemeProps("charts", "surfaces", rawProps, {
    rounded: "lg",
  } as const);
  const {
    title,
    description,
    config,
    labels = [],
    tableSeries = [],
    loading = false,
    error,
    empty = false,
    emptyText = "No chart data.",
    showTable = false,
    showCaption = true,
    responsive = true,
    width,
    height = 260,
    rounded: _rounded,
    labelFormatter = (label: string) => label,
    valueFormatter = (value: number) => new Intl.NumberFormat().format(value),
    theme: _themeInput,
    className,
    style,
    children,
    "data-balsa": dataBalsa,
    ...domProps
  } = props;
  void _rounded;
  void _themeInput;

  const rootRef = useRef<HTMLElement | null>(null);
  const plotRef = useRef<HTMLDivElement | null>(null);
  const [measuredWidth, setMeasuredWidth] = useState(0);
  const [paletteVersion, setPaletteVersion] = useState(0);
  const [reducedMotion, setReducedMotion] = useState(false);

  const resolvedWidth = width ?? measuredWidth;
  const resolvedHeight = Math.max(0, height);
  const renderable = resolvedWidth > 0 && resolvedHeight > 0;
  const chartStyle: CSSProperties = {
    height: `${resolvedHeight}px`,
    ...(width === undefined ? {} : { width: `${Math.max(0, width)}px`, maxWidth: responsive ? "100%" : undefined }),
  };
  const tableClasses = showTable ? "mt-balsa-xl overflow-x-auto" : "sr-only";

  const colors = useMemo(() => {
    void paletteVersion;
    const node = rootRef.current;
    if (!node) return Object.fromEntries(Object.keys(config).map((key) => [key, "currentColor"]));
    const styles = getComputedStyle(node);
    const surface = styles.getPropertyValue("--balsa-color-chart-surface").trim()
      || styles.getPropertyValue("--balsa-color-surface").trim();
    const foreground = styles.getPropertyValue("--balsa-color-chart-axis").trim()
      || styles.getPropertyValue("--balsa-color-surface-foreground").trim();
    return Object.fromEntries(Object.entries(config).map(([key, item], index) => {
      const role = item.color ?? defaultRoles[index % defaultRoles.length]!;
      const source = styles.getPropertyValue(`--balsa-color-${token(role)}`).trim() || foreground || "currentColor";
      return [key, ensureChartContrast(source, surface, foreground, 3)];
    }));
  }, [config, paletteVersion]);

  useEffect(() => {
    setPaletteVersion((current) => current + 1);
  }, [rawProps.theme]);

  useEffect(() => {
    function refreshWidth(): void {
      setMeasuredWidth(plotRef.current?.clientWidth ?? 0);
    }

    refreshWidth();
    let resizeObserver: ResizeObserver | undefined;
    let mutationObserver: MutationObserver | undefined;
    let media: MediaQueryList | undefined;

    function refreshMotion(): void {
      setReducedMotion(media?.matches ?? false);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(refreshWidth);
      if (plotRef.current) resizeObserver.observe(plotRef.current);
    }
    if (typeof MutationObserver !== "undefined") {
      mutationObserver = new MutationObserver(() => {
        setPaletteVersion((current) => current + 1);
      });
      let context: HTMLElement | null = rootRef.current;
      while (context) {
        mutationObserver.observe(context, {
          attributes: true,
          attributeFilter: ["style", "class", "data-palette", "data-theme", "data-theme-base"],
        });
        context = context.parentElement;
      }
    }
    if (typeof window.matchMedia === "function") {
      media = window.matchMedia("(prefers-reduced-motion: reduce)");
      refreshMotion();
      media.addEventListener("change", refreshMotion);
    }
    setPaletteVersion((current) => current + 1);

    return () => {
      resizeObserver?.disconnect();
      mutationObserver?.disconnect();
      media?.removeEventListener("change", refreshMotion);
    };
  }, []);

  const contextValue = useMemo(
    () => ({ config, colors, reducedMotion }),
    [config, colors, reducedMotion],
  );

  return (
    <BalsaThemeContext.Provider value={theme}>
      <BalsaChartContext.Provider value={contextValue}>
        <figure
          {...domProps}
          ref={rootRef}
          data-balsa={dataBalsa ?? "chart-container"}
          data-theme={theme.explicitPresentation?.id}
          data-theme-base={theme.explicitPresentation?.base}
          data-responsive={responsive}
          className={mergeClasses("text-balsa-foreground", className)}
          style={{ ...theme.explicitPresentation?.style, ...style } as CSSProperties}
        >
          <figcaption className={showCaption ? undefined : "sr-only"}>
            <h3 className="text-sm font-semibold leading-snug">{title}</h3>
            {description ? (
              <p className="mt-balsa-3xs text-xs text-balsa-muted-foreground">{description}</p>
            ) : null}
          </figcaption>
          {loading ? (
            <div style={chartStyle} className="grid place-items-center" aria-busy="true">
              <Spinner label="Loading chart" />
            </div>
          ) : error ? (
            <div style={chartStyle} className="grid place-items-center text-center text-balsa-destructive" role="alert">
              {error}
            </div>
          ) : empty ? (
            <div style={chartStyle} className="grid place-items-center text-center text-balsa-muted-foreground">
              {emptyText}
            </div>
          ) : (
            <div ref={plotRef} style={chartStyle} className="mt-balsa-lg min-w-0" aria-hidden="true">
              {renderable ? children?.({
                width: resolvedWidth,
                height: resolvedHeight,
                colors,
                reducedMotion,
              }) : null}
            </div>
          )}
          <div className={tableClasses}>
            <table className="w-full text-left text-sm tabular-nums">
              <caption>{title} data</caption>
              <thead>
                <tr>
                  <th scope="col">Category</th>
                  {tableSeries.map((item) => (
                    <th key={item.key} scope="col">{item.label}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {labels.map((label, index) => (
                  <tr key={`${label}-${index}`}>
                    <th scope="row">{labelFormatter(label, index)}</th>
                    {tableSeries.map((item) => (
                      <td key={item.key}>
                        {item.data[index] === undefined ? "—" : valueFormatter(item.data[index]!, item, index)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </figure>
      </BalsaChartContext.Provider>
    </BalsaThemeContext.Provider>
  );
}

import { VisCrosshair } from "@unovis/react";
import type { NumericAccessor } from "@unovis/ts";

export interface ChartCrosshairProps<Datum> {
  x?: NumericAccessor<Datum>;
  y?: NumericAccessor<Datum> | NumericAccessor<Datum>[];
  yStacked?: NumericAccessor<Datum>[];
  template?: (datum: Datum, x: number | Date, data: Datum[], leftNearestDatumIndex?: number) => string | HTMLElement;
}

export function ChartCrosshair<Datum>(props: ChartCrosshairProps<Datum>) {
  return <VisCrosshair {...props} circleRadius={5} />;
}

import { mergeClasses } from "./classes";
import { Icon } from "./Icon";
import { useChart } from "./chart";

export interface ChartLegendContentProps {
  items?: readonly string[];
  className?: string;
}

export function ChartLegendContent({ items, className }: ChartLegendContentProps) {
  const chart = useChart();
  const keys = items ?? Object.keys(chart.config);

  return (
    <ul
      data-balsa="chart-legend"
      className={mergeClasses(
        "flex flex-wrap items-center justify-center gap-x-balsa-lg gap-y-balsa-xs text-xs text-balsa-chart-axis",
        className,
      )}
    >
      {keys.map((key, index) => {
        const item = chart.config[key];
        return (
          <li key={key} className="flex items-center gap-balsa-2xs">
            {item?.icon ? (
              <Icon icon={item.icon} size="xs" />
            ) : (
              <span
                className="h-2.5 w-2.5 rounded-[var(--balsa-chart-marker-radius)] border border-current"
                style={{
                  backgroundColor: chart.colors[key],
                  borderStyle: index % 3 === 1 ? "dashed" : "solid",
                }}
                aria-hidden="true"
              />
            )}
            <span>{item?.label ?? key}</span>
          </li>
        );
      })}
    </ul>
  );
}

import { VisTooltip } from "@unovis/react";
import type { TooltipConfigInterface } from "@unovis/ts";

export type ChartTooltipProps = Pick<
  TooltipConfigInterface,
  "triggers" | "followCursor" | "allowHover" | "showDelay" | "hideDelay"
>;

export function ChartTooltip(props: ChartTooltipProps) {
  return <VisTooltip {...props} className="balsa-chart-tooltip" />;
}

import { Icon } from "./Icon";
import { useChart } from "./chart";

export interface ChartTooltipItem {
  key: string;
  value: string;
}

export interface ChartTooltipContentProps {
  label?: string;
  items: readonly ChartTooltipItem[];
}

export function ChartTooltipContent({ label, items }: ChartTooltipContentProps) {
  const chart = useChart();

  return (
    <div
      data-balsa="chart-tooltip-content"
      className="min-w-36 rounded-balsa-control border bg-balsa-chart-tooltip p-balsa-sm text-xs text-balsa-chart-tooltip-foreground shadow-balsa-overlay"
    >
      {label ? (
        <p className="mb-balsa-xs font-medium text-balsa-muted-foreground">{label}</p>
      ) : null}
      {items.map((item) => {
        const configItem = chart.config[item.key];
        return (
          <div key={item.key} className="flex items-center gap-balsa-xs py-balsa-4xs">
            {configItem?.icon ? (
              <Icon icon={configItem.icon} size="xs" />
            ) : (
              <span
                className="h-2 w-2 rounded-full"
                style={{ backgroundColor: chart.colors[item.key] }}
                aria-hidden="true"
              />
            )}
            <span className="text-balsa-muted-foreground">{configItem?.label ?? item.key}</span>
            <span className="ml-auto font-mono font-semibold tabular-nums">{item.value}</span>
          </div>
        );
      })}
    </div>
  );
}

import { createContext, useContext } from "react";
import type { IconComponent } from "./Icon";
import type { SemanticColor } from "./types";

export type ChartPaletteRole = SemanticColor | "neutral";

export interface ChartConfigItem {
  label: string;
  color?: ChartPaletteRole;
  icon?: IconComponent;
}

export type ChartConfig = Record<string, ChartConfigItem>;

export interface ChartTableSeries {
  key: string;
  label: string;
  data: readonly number[];
}

export interface ChartContextValue {
  config: Readonly<ChartConfig>;
  colors: Readonly<Record<string, string>>;
  reducedMotion: boolean;
}

export const BalsaChartContext = createContext<ChartContextValue | undefined>(undefined);

export function useChart(): ChartContextValue {
  const context = useContext(BalsaChartContext);
  if (!context) throw new Error("Chart components must be used inside ChartContainer.");
  return context;
}

interface Rgb {
  red: number;
  green: number;
  blue: number;
}

function parseColor(value: string): Rgb | undefined {
  const hex = value.trim().match(/^#([\da-f]{6})$/i)?.[1];
  if (hex) {
    return {
      red: Number.parseInt(hex.slice(0, 2), 16),
      green: Number.parseInt(hex.slice(2, 4), 16),
      blue: Number.parseInt(hex.slice(4, 6), 16),
    };
  }
  const rgb = value.trim().match(/^rgba?\(([-\d.]+)[, ]+([-\d.]+)[, ]+([-\d.]+)/i);
  if (!rgb) return undefined;
  return { red: Number(rgb[1]), green: Number(rgb[2]), blue: Number(rgb[3]) };
}

function channel(value: number): number {
  const normalized = value / 255;
  return normalized <= 0.04045 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
}

function contrast(first: Rgb, second: Rgb): number {
  const luminance = (color: Rgb) => 0.2126 * channel(color.red) + 0.7152 * channel(color.green) + 0.0722 * channel(color.blue);
  const a = luminance(first);
  const b = luminance(second);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}

function mix(first: Rgb, second: Rgb, amount: number): Rgb {
  return {
    red: Math.round(first.red + (second.red - first.red) * amount),
    green: Math.round(first.green + (second.green - first.green) * amount),
    blue: Math.round(first.blue + (second.blue - first.blue) * amount),
  };
}

function serialize(color: Rgb): string {
  return `rgb(${color.red} ${color.green} ${color.blue})`;
}

export function ensureChartContrast(colorValue: string, surfaceValue: string, foregroundValue: string, minimum: 3 | 4.5): string {
  const color = parseColor(colorValue);
  const surface = parseColor(surfaceValue);
  const foreground = parseColor(foregroundValue);
  if (!color || !surface || !foreground || contrast(color, surface) >= minimum) return colorValue;

  let low = 0;
  let high = 1;
  for (let iteration = 0; iteration < 12; iteration += 1) {
    const middle = (low + high) / 2;
    if (contrast(mix(color, foreground, middle), surface) >= minimum) high = middle;
    else low = middle;
  }
  return serialize(mix(color, foreground, high));
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

